// Classic Era / TBC Anniversary structured observations end to end: real GearExport 2c5e9b3 SavedVariables
// (generated by the unmodified collectors; see core/test/fixtures/gearexport-2c5e9b3/README.md) -> bridge ->
// store -> read model. These are automated fixtures, not live client captures.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { DashboardReadModel, SqliteSnapshotStore, foreverCompatibility, parseWowSyncExport } from "@wowsync-dashboard/core";
import { parseSavedExports, type SavedExport } from "../src/importSaved.ts";
import { buildWowSyncExport } from "../../core/test/fixtureBuilder.ts";

const FIXTURES = new URL("../../core/test/fixtures/gearexport-2c5e9b3/", import.meta.url);
const GENERATED = 1_789_000_005;
const NOW = GENERATED + 120;

function fixture(flavor: "classic-era" | "tbc-anniversary"): SavedExport {
  const path = new URL(`WoWSync-${flavor}.lua`, FIXTURES);
  const records = parseSavedExports(readFileSync(path, "utf8"), path.pathname);
  assert.equal(records.length, 1);
  return records[0]!;
}

type Obj = Record<string, any>;
const clone = <T>(value: T): T => structuredClone(value);

function withStore(fn: (store: SqliteSnapshotStore, read: DashboardReadModel) => void): void {
  const store = new SqliteSnapshotStore(":memory:");
  try { fn(store, new DashboardReadModel(store, () => NOW)); } finally { store.close(); }
}

function importFixture(store: SqliteSnapshotStore, record: SavedExport, characterState: unknown = record.characterState) {
  return store.importSnapshot(record.text!, characterState === undefined ? {} : { characterState });
}

/** The same character's next export with a later Generated value and an optional replacement sidecar. */
function laterExport(record: SavedExport, seconds: number): string {
  return record.text!.replace(/^Generated: (\d+)$/m, (_, value: string) => `Generated: ${Number(value) + seconds}`).replace(/observed=(\d+)/g, (_, value: string) => `observed=${Number(value) + seconds}`);
}

test("CLASSIC BRIDGE: real Era/TBC SavedVariables travel as a Classic state family, never labelled Retail", () => {
  for (const flavor of ["classic-era", "tbc-anniversary"] as const) {
    const record = fixture(flavor);
    const state = record.characterState as Obj;
    assert.equal(state.clientFamily, "Classic", flavor);
    assert.equal(state.formatVersion, 1);
    assert.match(state.sourceCharacterGuid, /^Player-/);
    for (const key of ["professionRecipes", "quests", "talents"]) assert.ok(state[key]?.data, `${flavor} ${key}`);
    assert.ok(state.reputation.character.data, `${flavor} reputation`);
    assert.equal(state.combatSpecialization, undefined);
    // Mutable attempt diagnostics are not part of the payload; the staleness flag is.
    assert.equal(state.professionRecipes.lastAttemptAt, undefined);
    assert.equal(state.professionRecipes.lastAttemptError, undefined);
    assert.equal(state.professionRecipes.lastAttemptStale, true);
    assert.equal(record.foreverGearObservation, undefined);
  }
});

test("CLASSIC IMPORT: recipes distinguish learned, visible-only, enchant identities, and exporter LAST_SEEN rows", () => withStore((store, read) => {
  const result = importFixture(store, fixture("classic-era"));
  assert.equal(result.characterState, "recorded");
  const professions = read.getCharacterProfessions({ version: "classic-era", name: "Torahn" });
  assert.equal(professions.status, "FOUND");
  if (professions.status !== "FOUND") return;
  const knowledge = professions.value.data!.recipeKnowledge as Obj;
  assert.equal(knowledge.evidence.state, "OBSERVED");
  assert.equal(knowledge.completeness, "partial", "an open-window list is never a full catalogue");

  const crafters = read.findRecipeCrafters({ version: "classic-era", nameContains: "copper" }).data!;
  const bracers = crafters.learned.find((row) => row.recipe.name === "Copper Bracers")!;
  assert.equal(bracers.recipe.knowledgeClass, "LEARNED");
  assert.equal(bracers.recipe.identityBasis, "RECIPE_KEY");
  assert.equal(bracers.recipe.recipeID, undefined, "Classic rows never get a manufactured recipe ID");
  // GearExport relabels the Blacksmithing rows LAST_SEEN once Enchanting was scanned; the learned claim itself was observed.
  assert.equal(bracers.recipe.evidence, "LAST_SEEN");
  assert.equal(bracers.recipe.learnedEvidence, "OBSERVED");
  assert.equal(bracers.recipe.outputKind, "ITEM");
  assert.equal(bracers.recipe.outputItemID, 2853);
  assert.deepEqual(bracers.recipe.reagentSlots.map((slot) => [slot.alternatives[0]?.itemID, slot.quantityRequired, slot.clientReportedCarried?.quantity]), [[2840, 2, 3]]);
  assert.equal(bracers.recipe.clientReportedCount?.meaning, "CLIENT_REPORTED_CRAFTABLE_AT_OBSERVATION");

  const enchant = read.findRecipeCrafters({ version: "classic-era", enchantID: 7418 }).data!;
  assert.equal(enchant.learned.length, 0, "a Craft-window row is not proof the enchant is learned");
  const visible = enchant.unresolved[0]!.recipe;
  assert.equal(visible.knowledgeClass, "VISIBLE_LEARNED_UNKNOWN");
  assert.equal(visible.learnedState, "UNKNOWN");
  assert.equal(visible.evidence, "OBSERVED");
  assert.equal(visible.outputKind, "ENCHANTMENT");
  assert.equal(visible.outputItemID, undefined, "an enchant identity is never an output item ID");
  assert.equal(visible.clientReportedCount?.meaning, "CLIENT_AVAILABLE_VALUE_NEUTRAL");
  assert.equal(read.findRecipeCrafters({ version: "classic-era", outputItemID: 7418 }).data!.unresolved.length, 0, "enchant IDs do not match item filters");
}));

test("CLASSIC REAGENTS: current complete bags decide carried sufficiency; unobserved bank stays UNKNOWN; other characters are separate", () => withStore((store, read) => {
  const record = fixture("classic-era");
  importFixture(store, record);
  // A second Era character on the same realm with 40 Copper Bars and an observed bank.
  store.importSnapshot(buildWowSyncExport({ generatedAt: GENERATED, character: { name: "Banko", realm: "Nightslayer", class: "Warrior", level: 20, clientVersion: "1.15.9", clientBuild: "69547" },
    bags: { containers: [{ id: 0, capacity: 16, items: [{ itemRef: "item:2840::::::::20:::::::::", name: "Copper Bar", qty: 40 }] }] }, bank: { containers: [{ id: -1, capacity: 24, items: [] }] } }));

  const vest = read.getRecipeReagentAvailability({ version: "classic-era", name: "Torahn", outputItemID: 10421 });
  assert.equal(vest.status, "FOUND");
  if (vest.status !== "FOUND") return;
  const data = vest.value.data as Obj;
  assert.equal(data.craftability, "NOT_ESTABLISHED");
  const copper = data.reagents[0].perAlternative[0];
  assert.equal(copper.carriedConclusion, "INSUFFICIENT_IN_COMPLETE_CURRENT_BAGS", "3 carried < 4 required");
  const holding = (owner: string, name: string) => copper.holdings.find((row: Obj) => row.ownerScope === owner && row.name === name);
  assert.deepEqual([holding("CRAFTER_BAGS", "Torahn").state, holding("CRAFTER_BAGS", "Torahn").quantity], ["OBSERVED", 3]);
  assert.equal(holding("CRAFTER_BANK", "Torahn").state, "UNKNOWN", "an unobserved bank is not an empty bank");
  assert.equal(holding("CRAFTER_BANK", "Torahn").quantity, undefined);
  assert.deepEqual([holding("OTHER_CHARACTER", "Banko").quantity, holding("OTHER_CHARACTER", "Banko").usableForCraftingWithoutMove], [40, false], "same-realm holdings are listed, never assumed transferable");
  assert.match(data.sharedStorage, /guild bank contents are not captured/);

  const minorHealth = read.getRecipeReagentAvailability({ version: "classic-era", name: "Torahn", enchantID: 7418 });
  assert.equal(minorHealth.status === "FOUND" && (minorHealth.value.data as Obj).reagents[0].perAlternative[0].carriedConclusion, "SUFFICIENT_IN_CURRENT_BAGS");
  assert.match(minorHealth.status === "FOUND" ? (minorHealth.value.data as Obj).semantics : "", /does not establish that the recipe is learned/);

  const missing = read.getRecipeReagentAvailability({ version: "classic-era", name: "Torahn", recipeName: "Copper Chain Pants" });
  assert.equal(missing.status === "FOUND" && missing.value.provenance.state, "UNKNOWN", "no fabricated recipe");
  assert.throws(() => read.getRecipeReagentAvailability({ version: "classic-era", name: "Torahn", outputItemID: 10421, enchantID: 7418 }), /exactly one/);
}));

test("CLASSIC PROGRESSION: quests, completed-ID lookups, visible reputation, and talents keep their evidence", () => withStore((store, read) => {
  importFixture(store, fixture("tbc-anniversary"));
  const quests = read.getCharacterQuests({ version: "tbc-anniversary", name: "Torahn", completedQuestIDs: [870, 12345] });
  assert.equal(quests.status, "FOUND");
  if (quests.status !== "FOUND") return;
  const q = quests.value.data!;
  assert.equal(q.version, "tbc-anniversary");
  assert.equal(q.state, "OBSERVED");
  assert.deepEqual(q.active!.map((row) => [row.questID, row.rowEvidence, row.isComplete, row.turnInReadinessState]), [[844, "OBSERVED", false, "UNKNOWN"], [869, "OBSERVED", true, "UNKNOWN"]]);
  assert.deepEqual(q.completedHistory.lookup, [{ questID: 870, state: "OBSERVED" }, { questID: 12345, state: "NOT_IN_RETURNED_HISTORY" }]);
  assert.equal(q.completedHistory.returnedCount, 4);

  const progression = read.getCharacterProgression({ version: "tbc-anniversary", name: "Torahn" });
  assert.equal(progression.status, "FOUND");
  if (progression.status !== "FOUND") return;
  const { reputation, talents } = progression.value.data!;
  assert.equal(reputation.coverage, "VISIBLE_REPUTATION_ROWS_ONLY");
  assert.equal(reputation.completeness, "partial");
  assert.deepEqual(reputation.factions.map((row) => [row.name, row.factionID, row.standingLabel]), [["Orgrimmar", 76, "Friendly"], ["Thunder Bluff", 81, "Honored"], ["Booty Bay", 21, "Neutral"]]);
  assert.equal(talents.distribution, "0/21/9");
  assert.equal(talents.trees[1]!.talents.some((talent) => talent.name === "Shield Specialization"), false, "rank-0 talents are omitted by default");

  // Other versions answer honestly instead of borrowing Classic shapes.
  const retail = read.getCharacterProgression({ version: "retail", name: "Torahn" });
  assert.equal(retail.status === "FOUND" && retail.value.provenance.state, "UNKNOWN");
  const retailQuests = read.getCharacterQuests({ version: "retail", name: "Torahn" });
  assert.equal(retailQuests.status === "FOUND" && retailQuests.value.provenance.state, "UNKNOWN");
}));

test("CLASSIC HISTORY: a later export without sidecars carries every domain forward as LAST_SEEN; a recreated character does not inherit", () => withStore((store, read) => {
  const record = fixture("classic-era");
  importFixture(store, record);
  const second = store.importSnapshot(laterExport(record, 600));
  assert.equal(second.isLatest, true);
  assert.equal(second.snapshot.parsed.characterState, undefined, "Classic sidecars are not copied into later stored snapshots");

  const knowledge = (read.getCharacterProfessions({ version: "classic-era", name: "Torahn" }) as Obj).value.data.recipeKnowledge;
  assert.deepEqual([knowledge.evidence.state, knowledge.evidence.sourceSnapshotId], ["LAST_SEEN", 1]);
  const enchant = read.findRecipeCrafters({ version: "classic-era", enchantID: 7418 }).data!.unresolved[0]!.recipe;
  assert.equal(enchant.evidence, "LAST_SEEN", "a carried row is historical even if it was OBSERVED in its own snapshot");

  const quests = read.getCharacterQuests({ version: "classic-era", name: "Torahn" });
  assert.equal(quests.status === "FOUND" && quests.value.data!.state, "LAST_SEEN");
  assert.equal(quests.status === "FOUND" && quests.value.provenance.snapshotId, 1);
  const progression = read.getCharacterProgression({ version: "classic-era", name: "Torahn" });
  assert.equal(progression.status === "FOUND" && progression.value.data!.reputation.state, "LAST_SEEN");
  assert.equal(progression.status === "FOUND" && progression.value.data!.talents.sourceSnapshotId, 1);
  const state = (read.getCharacterState({ version: "classic-era", name: "Torahn" }) as Obj).value.data.structuredObservations;
  assert.deepEqual([state.recipes.state, state.quests.state, state.talents.sourceSnapshotId], ["LAST_SEEN", "LAST_SEEN", 1]);

  // A same-name character with a different WoWSyncDB GUID (deleted and recreated) sends only talents.
  const recreated = clone(record.characterState) as Obj;
  recreated.sourceCharacterGuid = "Player-4385-0BADF00D";
  delete recreated.professionRecipes; delete recreated.quests; delete recreated.reputation;
  store.importSnapshot(laterExport(record, 1200), { characterState: recreated });
  const after = read.getCharacterProfessions({ version: "classic-era", name: "Torahn" }) as Obj;
  assert.equal(after.value.data.recipeKnowledge.status.state, "UNKNOWN", "older recipes are not attributed to a different GUID");
  assert.equal((read.getCharacterQuests({ version: "classic-era", name: "Torahn" }) as Obj).value.data.state, "UNKNOWN");
  assert.equal((read.getCharacterProgression({ version: "classic-era", name: "Torahn" }) as Obj).value.data.talents.state, "OBSERVED");
}));

test("CLASSIC ISOLATION: Era and TBC sidecars never cross versions, families, or profiles", () => withStore((store, read) => {
  const era = fixture("classic-era");
  const tbc = fixture("tbc-anniversary");
  // A TBC sidecar sent with an Era export (or vice versa) is rejected as a whole.
  assert.equal(store.importSnapshot(era.text!, { characterState: tbc.characterState }).characterState, "invalid-or-unsupported");
  assert.equal(store.importSnapshot(tbc.text!, { characterState: era.characterState }).characterState, "invalid-or-unsupported");
  // A Classic family sidecar on a Retail or Forever export is never accepted.
  const retailText = buildWowSyncExport({ generatedAt: GENERATED, character: { name: "Torahn", realm: "Nightslayer", clientFamily: "Retail", clientVersion: "12.0.5", clientBuild: "60000", interface: "120005" } });
  assert.equal(store.importSnapshot(retailText, { characterState: era.characterState }).characterState, "invalid-or-unsupported");
  // A tampered profile on one domain drops only that domain.
  const tampered = clone(era.characterState) as Obj;
  tampered.talents.data.clientProfile = "Classic:5:20506";
  tampered.quests.data.active[0].questID = -1;
  const reimport = store.importSnapshot(laterExport(era, 60), { characterState: tampered });
  assert.equal(reimport.characterState, "recorded");
  assert.equal(reimport.snapshot.parsed.characterState?.talents, undefined);
  assert.equal(reimport.snapshot.parsed.characterState?.quests, undefined);
  assert.ok(reimport.snapshot.parsed.characterState?.professionRecipes);
  // Classic rows never carry a numeric recipe ID; one that does is a different contract and is dropped.
  const withID = clone(era.characterState) as Obj;
  withID.professionRecipes.data.professions[0].recipes[0].recipeID = 2663;
  assert.equal(store.importSnapshot(laterExport(era, 120), { characterState: withID }).snapshot.parsed.characterState?.professionRecipes, undefined);

  importFixture(store, tbc);
  assert.deepEqual(read.findRecipeCrafters({ version: "tbc-anniversary", outputItemID: 2853 }).data!.learned.map((row) => row.identityKey), ["tbc-anniversary::dreamscythe::torahn"]);
  assert.deepEqual(read.findRecipeCrafters({ version: "classic-era", outputItemID: 2853 }).data!.learned.map((row) => row.identityKey), ["classic-era::nightslayer::torahn"]);
  assert.equal(read.findRecipeCrafters({ version: "forever", outputItemID: 2853 }).data!.learned.length, 0);
}));

test("CLASSIC RE-IMPORT: the same export with a partial sidecar keeps earlier domains, labelled LAST_SEEN", () => withStore((store) => {
  const record = fixture("classic-era");
  importFixture(store, record);
  const partial = clone(record.characterState) as Obj;
  delete partial.talents;
  const result = importFixture(store, record, partial);
  assert.equal(result.isDuplicate, true);
  const stored = store.listSnapshots(result.character.identityKey)[0]!.parsed.characterState!;
  assert.equal(stored.talents?.status.state, "LAST_SEEN");
  assert.equal(stored.quests?.status.state, "OBSERVED");
}));

test("CLASSIC EXPORTER LABELS: rows the exporter kept as LAST_SEEN stay historical in quests and completed history", () => withStore((store, read) => {
  const record = fixture("classic-era");
  const state = clone(record.characterState) as Obj;
  state.quests.data.active[0].evidence = "LAST_SEEN";
  state.quests.data.active[0].lastSeenAt = GENERATED - 100;
  state.quests.data.completedHistory.quests[0].evidence = "LAST_SEEN";
  state.quests.data.completedHistory.state = "PARTIAL";
  importFixture(store, record, state);
  const quests = read.getCharacterQuests({ version: "classic-era", name: "Torahn", completedQuestIDs: [840, 9999] }) as Obj;
  const data = quests.value.data;
  assert.equal(data.completeness, "partial");
  assert.deepEqual(data.active.map((row: Obj) => [row.questID, row.rowEvidence, row.titleState]), [[844, "LAST_SEEN", "LAST_SEEN"], [869, "OBSERVED", "OBSERVED"]]);
  assert.equal(data.completedHistory.lastSeenCount, 1);
  assert.deepEqual(data.completedHistory.lookup, [{ questID: 840, state: "LAST_SEEN" }, { questID: 9999, state: "UNKNOWN" }], "absence from a partial history is not 'not completed'");
}));

test("CLASSIC ACCOUNT FACTS: profession coverage and reputation facts include Classic evidence without Retail semantics", () => withStore((store, read) => {
  importFixture(store, fixture("classic-era"));
  const facts = read.getAccountFacts({ version: "classic-era" }).data!;
  const torahn = facts.professions.byCharacter.find((row) => row.name === "Torahn") as Obj;
  assert.equal(torahn.recipeKnowledge.status, "OBSERVED");
  const rep = facts.reputation.byCharacter.find((row) => row.name === "Torahn")!;
  assert.deepEqual(rep.factions.map((row) => row.name), ["Orgrimmar", "Thunder Bluff", "Booty Bay"]);
}));

test("FOREVER COMPATIBILITY: exporter claims are parsed verbatim and compared with the Dashboard's exact-profile verdict", () => {
  const forever = (version: string, build: string, iface: string, claim?: string) => parseWowSyncExport(buildWowSyncExport({ generatedAt: GENERATED, character: { name: "Rordin", realm: "Classic Beta PvP 2", clientFamily: "Forever", clientVersion: version, clientBuild: build, interface: iface, ...(claim ? { compatibility: claim, compatibilityNote: "Forever project identified; this client build has not been compatibility-tested." } : {}) } })).character;
  const verified = forever("1.60.1", "70338", "16001", "VERIFIED_PROFILE");
  assert.equal(verified.exporterCompatibility, "VERIFIED_PROFILE");
  assert.deepEqual(foreverCompatibility(verified), { dashboard: "VERIFIED", exporter: "VERIFIED_PROFILE", exporterNote: "Forever project identified; this client build has not been compatibility-tested.", agreement: "AGREE" });
  assert.equal(foreverCompatibility(forever("1.61.0", "71234", "16100", "UNVERIFIED_BUILD")).agreement, "AGREE");
  assert.equal(foreverCompatibility(forever("1.61.0", "71234", "16100", "VERIFIED_PROFILE")).agreement, "DISAGREE", "an optimistic exporter claim is surfaced, not trusted");
  assert.equal(foreverCompatibility(forever("1.61.0", "70338", "16100")).dashboard, "UNVERIFIED_BUILD", "a known build number on another version/interface is not a verified profile");
  assert.equal(foreverCompatibility(forever("1.60.1", "70291", "16001")).agreement, "EXPORTER_NOT_STATED");
});

test("RETAIL BRIDGE REGRESSION: Retail sidecars keep the Retail family and gain only the source GUID", () => {
  const retailText = buildWowSyncExport({ generatedAt: GENERATED, character: { name: "Virek", realm: "Cairne", clientFamily: "Retail", clientVersion: "12.0.5", clientBuild: "60000", interface: "120005" } });
  const lua = `WoWSyncDB = { ["schemaVersion"] = 1, ["characters"] = { ["Player-1-AAAA"] = { ["identity"] = { ["guid"] = "Player-1-AAAA", ["name"] = "Virek", ["realm"] = "Cairne" }, ["latestExport"] = { ["text"] = ${JSON.stringify(retailText)}, ["generatedAt"] = ${GENERATED} }, ["sections"] = { ["reputation"] = { ["data"] = { ["formatVersion"] = 1, ["factions"] = {} }, ["observedAt"] = ${GENERATED}, ["completeness"] = "partial" } } } } }`;
  const [record] = parseSavedExports(lua, "retail.lua");
  const state = record!.characterState as Obj;
  assert.equal(state.clientFamily, "Retail");
  assert.equal(state.sourceCharacterGuid, "Player-1-AAAA");
  assert.ok(state.reputation.character);
  const store = new SqliteSnapshotStore(":memory:");
  try { assert.equal(store.importSnapshot(record!.text!, { characterState: state }).characterState, "recorded"); } finally { store.close(); }
});

